<script>
document.addEventListener('click', function (e) {
  var m = e.target.closest('[data-team-id]'); if (m) document.getElementById('ch-member-team').value = m.getAttribute('data-team-id');
  var b = e.target.closest('[data-team]'); if (!b) return;
  var f = document.getElementById('ch-team-form'), t = JSON.parse(b.getAttribute('data-team') || '{}');
  f.reset(); f.id.value = t.id || 0; f.name.value = t.name || ''; f.description.value = t.description || ''; f.assign_mode.value = t.assign_mode || 'least_loaded'; f.timezone.value = t.timezone || '';
  [['active', t.id ? !!t.active : true], ['is_default', !!t.is_default]].forEach(function (p) { var inp = f.querySelector('[name="' + p[0] + '"]'), sw = inp.parentNode; inp.value = p[1] ? 1 : 0; sw.classList.toggle('on', p[1]); sw.setAttribute('aria-checked', p[1]); });
});
</script>
